// MARK: - Runtime lookup by Italian source text

extension L10n {
    /// Translates an Italian source label returned by the API (e.g. group labels "Dovute", "Oggi"),
    /// exactly like the web's `translate(language, source, values)`: unknown sources fall back to the
    /// Italian text, and `{name}` placeholders without a value are left as-is.
    static func lookup(italian source: String, _ values: [String: String] = [:]) -> String {
        guard let key = L10nIndex.sourceIndex[source] else { return L10nIndex.substitute(source, values) }
        guard let names = L10nIndex.placeholderNames[key] else { return LocalizedStrings.shared.string(key) }
        return LocalizedStrings.shared.format(key, names.map { values[$0] ?? "{" + $0 + "}" })
    }

    /// Catalog key for an Italian source string, if the catalog has it.
    static func key(italian source: String) -> String? { L10nIndex.sourceIndex[source] }
}

/// Data behind `L10n.lookup(italian:)`; kept out of `L10n` so it cannot clash with accessor names.
enum L10nIndex {
    static func substitute(_ text: String, _ values: [String: String]) -> String {
        guard !values.isEmpty, text.contains("{") else { return text }
        var result = ""
        var rest = Substring(text)
        while let open = rest.firstIndex(of: "{") {
            result += rest[..<open]
            let after = rest.index(after: open)
            if let close = rest[after...].firstIndex(of: "}"),
               case let name = rest[after..<close],
               !name.isEmpty, name.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "_" }),
               let value = values[String(name)] {
                result += value
                rest = rest[rest.index(after: close)...]
            } else {
                result += "{"
                rest = rest[after...]
            }
        }
        result += rest
        return result
    }

